(()=>{'use strict';const $=s=>document.querySelector(s),pages=['home','levels','editor','profile','settings'],key='gdps-editor-projects-v1',bestKey='gdps-editor-best-v1';let projects=[];try{projects=JSON.parse(localStorage.getItem(key)||'[]')}catch{}
function persist(){localStorage.setItem(key,JSON.stringify(projects))}
function go(p){pages.forEach(x=>$('#page-'+x).classList.toggle('active',x===p));document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));if(p==='home'||p==='levels')render();if(p==='profile')stats();if(p==='editor')setTimeout(()=>window.dispatchEvent(new Event('resize')),50);window.scrollTo(0,0)}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));setTimeout(()=>$('#bootScreen').classList.add('boot-done'),900);
function save(){const d={...window.GDPSLevel.getData(),name:$('#nameInput').value.trim()||'Без названия',music:window.GDPSMusic?.getMetadata()||null,updated:Date.now()};const i=projects.findIndex(x=>x.name===d.name);if(i<0)projects.unshift(d);else projects[i]=d;persist();render();stats();$('#saveState').textContent='СОХРАНЕНО ЛОКАЛЬНО'}
$('#saveBtn').onclick=save;
function card(p){const el=document.createElement('article');el.className='level-card';const art=document.createElement('div');art.className='level-preview '+p.background;art.innerHTML='<span>◆</span><small>GDPS / LEVEL</small>';const info=document.createElement('div');info.className='level-info';const title=document.createElement('b');title.textContent=p.name;const meta=document.createElement('small');meta.textContent=(p.objects?.length||0)+' объектов · '+new Date(p.updated||Date.now()).toLocaleDateString('ru-RU');const actions=document.createElement('div');actions.className='level-actions';const play=document.createElement('button');play.textContent='ИГРАТЬ';play.className='level-play';play.onclick=()=>window.GDPSGame.start(p);const open=document.createElement('button');open.textContent='ОТКРЫТЬ';open.onclick=()=>{window.GDPSLevel.load(p);window.GDPSMusic?.setMetadata(p.music||null);$('#nameInput').value=p.name;go('editor')};const exp=document.createElement('button');exp.textContent='ЭКСПОРТ';exp.onclick=()=>{const blob=new Blob([JSON.stringify(p,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(p.name.replace(/[^\w-]+/g,'_')||'level')+'.json';a.click();URL.revokeObjectURL(a.href)};const del=document.createElement('button');del.textContent='УДАЛИТЬ';del.onclick=()=>{projects=projects.filter(x=>x!==p);persist();render();stats()};actions.append(play,open,exp,del);info.append(title,meta,actions);el.append(art,info);return el}
function render(){const q=($('#levelSearch')?.value||'').toLowerCase(),list=projects.filter(p=>p.name.toLowerCase().includes(q));if($('#levelSort')?.value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));[['recentList',projects.slice(0,3)],['allLevels',list]].forEach(([id,arr])=>{const node=$('#'+id);node.replaceChildren();arr.forEach(p=>node.append(card(p)));if(!arr.length){const empty=document.createElement('div');empty.className='empty-card';empty.textContent='Пока нет проектов. Создай свой первый уровень!';node.append(empty)}})}
function achievements(){const wins=Object.keys(JSON.parse(localStorage.getItem(bestKey)||'{}')).length;const items=[];if(projects.length)items.push('Первый проект');if(projects.some(p=>(p.objects||[]).length>=20))items.push('Архитектор · 20 объектов');if(wins)items.push('Первое прохождение');$('#achievementList').textContent=items.length?items.join(' · '):'Пока не открыто';$('#statWins').textContent=wins}
function stats(){$('#statLevels').textContent=projects.length;$('#statObjects').textContent=projects.reduce((n,p)=>n+(p.objects?.length||0),0);achievements()}
$('#levelSearch').oninput=render;$('#levelSort').onchange=render;$('#settingGrid').onchange=e=>{$('#gridToggle').checked=e.target.checked;$('#gridToggle').dispatchEvent(new Event('change'))};$('#settingSnap').onchange=e=>$('#snapToggle').checked=e.target.checked;$('#settingMotion').onchange=e=>document.body.classList.toggle('no-motion',!e.target.checked);$('#settingTheme').onchange=e=>document.documentElement.dataset.theme=e.target.value;
$('#settingSound')?.addEventListener('change',e=>localStorage.setItem('gdps-editor-sound',e.target.checked?'1':'0'));
render();stats()})();